SELECT M.MEMBER_NAME, R.REVIEW_TEXT, R.REVIEW_DATE FROM MEMBER_PROFILE M JOIN REST_REVIEW R ON M.MEMBER_ID = R.MEMBER_ID WHERE R.MEMBER_ID = (SELECT R.MEMBER_ID FROM MEMBER_PROFILE M JOIN REST_REVIEW R ON M.MEMBER_ID = R.MEMBER_ID GROUP BY R.MEMBER_ID ORDER BY COUNT(*) DESC LIMIT 1) ORDER BY R.REVIEW_DATE, R.REVIEW_TEXT;